(function(){
'use strict';
var STATE_KEY='welog-pair-sheet-v4',LAYOUT_KEY='welog-section-layout-v2';
var sheet=document.getElementById('sheet'),controls=document.getElementById('controls');if(!sheet||!controls)return;
function readJSON(k){try{return JSON.parse(localStorage.getItem(k)||'{}')||{}}catch(e){return{}}}
function writeJSON(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){console.error(e);return false}}
function normFont(v){if(/^KoPub Dotum/.test(v||''))return'KoPub Dotum Medium';if(/^KoPub Batang/.test(v||''))return'KoPub Batang Medium';if(!v||v==='__default__')return'Pretendard';return v}
function fontStack(v){v=normFont(v);if(v==='Pretendard')return'"WeLogMasterPretendard",sans-serif';if(v==='Noto Sans KR')return'"WeLogMasterNoto",sans-serif';if(v==='KoPub Dotum Medium')return'"WeLogMasterDotum",sans-serif';if(v==='KoPub Batang Medium')return'"WeLogMasterBatang",serif';if(v==='__system__')return'system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif';return'"'+String(v).replace(/"/g,'')+'","Noto Sans KR",sans-serif'}
function currentFont(){var sel=controls.querySelector('select[data-path="font"]'),s=readJSON(STATE_KEY);return normFont((sel&&sel.value)||s.font||'Pretendard')}
function persistFont(v){var s=readJSON(STATE_KEY);s.font=normFont(v);writeJSON(STATE_KEY,s)}
function applyFont(root){if(!root)return;var f=fontStack(currentFont());document.documentElement.style.setProperty('--welog-master-sheet-font',f);root.style.setProperty('--welog-master-sheet-font',f);root.style.setProperty('font-family',f,'important')}
function layoutDefaults(){return{pair:{scale:100,x:0,y:0},characters:{scale:100,x:0,y:0},center:{scale:100,x:0,y:0,crop:{top:0,right:0,bottom:0,left:0}},ok:{scale:100,x:0,y:0},credit:{scale:100,x:0,y:0}}}
function layout(){var d=layoutDefaults(),s=readJSON(LAYOUT_KEY);Object.keys(d).forEach(function(k){if(!s[k])return;d[k].scale=Math.max(55,Math.min(170,Number(s[k].scale)||100));d[k].x=Math.max(-420,Math.min(420,Number(s[k].x)||0));d[k].y=Math.max(-420,Math.min(420,Number(s[k].y)||0));if(k==='center'&&s[k].crop)d[k].crop={top:Number(s[k].crop.top)||0,right:Number(s[k].crop.right)||0,bottom:Number(s[k].crop.bottom)||0,left:Number(s[k].crop.left)||0}});return d}
function ensureFooterZones(root){var block=root.querySelector('.sheet-commission-footer .commission-block');if(!block)return;var ok=block.querySelector('.welog-ok-zone');if(!ok){var kids=Array.from(block.children),d=kids.find(function(x){return x.tagName==='DIV'&&!x.classList.contains('welog-credit-zone')});if(d)d.classList.add('welog-ok-zone')}var cr=block.querySelector('.welog-credit-zone');if(!cr){cr=document.createElement('div');cr.className='welog-credit-zone';var sm=Array.from(block.children).find(function(x){return x.tagName==='SMALL'}),b=Array.from(block.children).find(function(x){return x.tagName==='B'});if(sm)cr.appendChild(sm);if(b)cr.appendChild(b);block.appendChild(cr)}}
function applyLayout(root){if(!root)return;ensureFooterZones(root);var s=layout(),map={pair:[root.querySelector('.pair-title-display')],characters:[root.querySelector('.profile.left'),root.querySelector('.profile.right')],center:[root.querySelector('.center')],ok:[root.querySelector('.welog-ok-zone')],credit:[root.querySelector('.welog-credit-zone')]};Object.keys(map).forEach(function(k){map[k].filter(Boolean).forEach(function(el){var d=s[k];el.dataset.welogLayoutPart=k;el.style.setProperty('transform','translate('+d.x+'px,'+d.y+'px) scale('+(d.scale/100)+')','important');el.style.setProperty('transform-origin','center center','important');if(k==='center'){var c=d.crop||{};el.style.setProperty('clip-path','inset('+(c.top||0)+'% '+(c.right||0)+'% '+(c.bottom||0)+'% '+(c.left||0)+'%)','important')}})})}
var raf=0;function sync(){raf=0;applyFont(sheet);applyLayout(sheet)}function schedule(){if(!raf)raf=requestAnimationFrame(sync)}
controls.addEventListener('input',function(e){if(e.target&&e.target.matches('select[data-path="font"]')){persistFont(e.target.value);schedule()}},true);controls.addEventListener('change',function(e){if(e.target&&e.target.matches('select[data-path="font"]')){persistFont(e.target.value);schedule()}},true);
/* Reapply only after the app actually rebuilds sheet children. Attribute/style changes do not retrigger this observer. */
new MutationObserver(schedule).observe(sheet,{childList:true,subtree:false});
window.addEventListener('pageshow',schedule);window.addEventListener('load',function(){schedule();setTimeout(schedule,80);setTimeout(schedule,300)});document.addEventListener('visibilitychange',function(){if(!document.hidden)schedule()});
function replaceSaveButton(){var old=document.getElementById('printBtn');if(!old)return null;var b=old.cloneNode(true);old.replaceWith(b);b.id='printBtn';b.addEventListener('click',savePng);return b}
async function savePng(e){if(e){e.preventDefault();e.stopPropagation()}var btn=document.getElementById('printBtn');if(!window.html2canvas||!sheet)return;var oldText=btn.textContent;btn.disabled=true;btn.textContent='저장 중…';var host=null;try{schedule();await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});if(document.fonts&&document.fonts.ready)await document.fonts.ready;host=document.createElement('div');host.className='welog-master-export-host';var clone=sheet.cloneNode(true);clone.removeAttribute('id');clone.classList.add('welog-master-export');clone.style.transform='none';clone.style.margin='0';clone.style.zoom='1';applyFont(clone);applyLayout(clone);host.appendChild(clone);document.body.appendChild(host);await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var canvas=await html2canvas(clone,{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#fff',logging:false,imageTimeout:20000,scrollX:0,scrollY:0});var blob=await new Promise(function(resolve){canvas.toBlob(resolve,'image/png')});if(!blob)throw new Error('PNG blob creation failed');var url=URL.createObjectURL(blob),a=document.createElement('a'),st=readJSON(STATE_KEY);a.href=url;a.download=((st.pairName||'WeLog').trim()||'WeLog')+'.png';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},1000)}catch(err){console.error('WeLog PNG save failed',err);alert('PNG 저장에 실패했습니다.')}finally{if(host)host.remove();btn.disabled=false;btn.textContent=oldText}}
replaceSaveButton();sync();setTimeout(sync,50);setTimeout(sync,250);
})();